style.css:
button {
  color: #1D9AF2;
  background-color: #292D3E;
  border: 1px solid #1D9AF2;
  border-radius: 4px;
  padding: 0 15px;
  cursor: pointer;
  height: 32px;
  font-size: 14px;
  transition: all 0.2s ease-in-out;
  opacity: 0.5;
}
button:hover{
  opacity: 1;
}




body { background-color: #162b6c !important; }
